import { createReadable } from './readable.js';
/**
 * Create a tuple of `ReadableWritablePair` streams connected to each other.
 */ export function createConnection() {
    const [toA, controllerA] = createReadable();
    const [toB, controllerB] = createReadable();
    const fromA = new WritableStream({
        write (msg) {
            controllerB.enqueue(msg);
        },
        close () {
            controllerB.close();
        }
    });
    const fromB = new WritableStream({
        write (msg) {
            controllerA.enqueue(msg);
        },
        close () {
            controllerA.close();
        }
    });
    return [
        {
            readable: toA,
            writable: fromA
        },
        {
            readable: toB,
            writable: fromB
        }
    ];
}
